edits.after:
sample_accum = ep->sample_accum + ep->sample_rem;
if (sample_accum >= ep->pps) {
	sample_accum -= ep->pps;
	ret = ep->packsize[1];
} else {
	ret = ep->packsize[0];
}

if (ret > ep->maxframesize)
	ret = ep->maxframesize;

if (avail && ret >= avail)
	ret = -EAGAIN;
else
	ep->sample_accum = sample_accum;

return ret;

